WHERE eventid=87;

UPDATE savbillnotification.tblmevent
SET  mvnoid=1
WHERE mvnoid=2 and servicetype="BSS";

			CREATE PROCEDURE IF NOT EXISTS updates_mvnoid(IN old_mvnoid INT, IN new_mvnoid INT)
			BEGIN
    DECLARE tableName VARCHAR(100);
    DECLARE done BOOLEAN DEFAULT FALSE;

    DECLARE cur CURSOR FOR
			SELECT TABLE_NAME
			FROM INFORMATION_SCHEMA.COLUMNS
			WHERE TABLE_SCHEMA = 'savbillnotification'
			  AND COLUMN_NAME LIKE '%mvnoid%'
			  AND TABLE_NAME NOT IN (
									 'tblmmvno', 'tblmstaff',
									 'tblmrole','tblmsmsconfig','tblmsmsconfigmapping','tblmemailconfig','tblmsystemconfig'
				);

			DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
   	SET FOREIGN_KEY_CHECKS = 0;

			OPEN cur;
			read_loop: LOOP
        FETCH cur INTO tableName;
        IF done THEN
            LEAVE read_loop;
			END IF;
        SET @sql = CONCAT('UPDATE ', tableName, ' SET mvnoId =',new_mvnoid,' WHERE mvnoId = ', old_mvnoid ,';');
			select @sql;
			PREPARE stmt FROM @sql;
			EXECUTE stmt;
			DEALLOCATE PREPARE stmt;
			END LOOP;
			CLOSE cur;
			SET FOREIGN_KEY_CHECKS = 1;

			END//

			CREATE PROCEDURE IF NOT EXISTS updates_mvnoid(IN old_mvnoid INT, IN new_mvnoid INT)
			BEGIN
    DECLARE tableName VARCHAR(100);
    DECLARE done BOOLEAN DEFAULT FALSE;

    DECLARE cur CURSOR FOR
			SELECT TABLE_NAME
			FROM INFORMATION_SCHEMA.COLUMNS
			WHERE TABLE_SCHEMA = 'savbillnotification'
			  AND COLUMN_NAME LIKE '%mvnoid%'
			  AND TABLE_NAME NOT IN (
									 'tblmmvno', 'tblmstaff','tblmrole','tblmsmsconfig','tblmsmsconfigmapping',
			                         'tblmemailconfig','tblmsystemconfig','tblmtemplate','tblmevent'
				);

			DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
   	SET FOREIGN_KEY_CHECKS = 0;

			OPEN cur;
			read_loop: LOOP
        FETCH cur INTO tableName;
        IF done THEN
            LEAVE read_loop;
			END IF;
        SET @sql = CONCAT('UPDATE ', tableName, ' SET mvnoId =',new_mvnoid,' WHERE mvnoId = ', old_mvnoid ,';');
			select @sql;
			PREPARE stmt FROM @sql;
			EXECUTE stmt;
			DEALLOCATE PREPARE stmt;
			END LOOP;
			CLOSE cur;
			SET FOREIGN_KEY_CHECKS = 1;

			END//

        	SET @nextId = (SELECT COALESCE(MAX(emailconfigid), 0) + 1 FROM TBLMEMAILCONFIG);

			INSERT INTO TBLMEMAILCONFIG (emailconfigid, username, password, smtpauth, authtype, hostserver, port, mvnoid, servicetype)
			VALUES (@nextId, 'notification.test@savbillnet.tech', 'SAVBILL@2023', 1, 'StartTLS', 'smtp-mail.outlook.com', '587', '1', 'BSS');

			-- Declare and calculate the next available smsconfigid

        	SET @newSmsConfigId = (SELECT COALESCE(MAX(smsconfigid), 0) + 1 FROM TBLMSMSCONFIG);
			SET @newSmsConfigmappingId = (SELECT COALESCE(MAX(smsconfigmappingid),0)+1 FROM tblmsmsconfigmapping);
        -- Insert into TBLMSMSCONFIG with the calculated smsconfigid
			INSERT INTO TBLMSMSCONFIG (smsconfigid, smsurl, mvnoid)
			VALUES (@newSmsConfigId, 'http://makemysms.in/api/sendsms.php?', 1);

			-- Insert related entries into TBLMSMSCONFIGMAPPING using the new smsconfigid
			INSERT INTO TBLMSMSCONFIGMAPPING (smsconfigmappingid, smsconfigid, parameter, value, mvnoid)
			VALUES (@newSmsConfigmappingId, @newSmsConfigId, 'username', 'savbillnettech', 1);

			INSERT INTO TBLMSMSCONFIGMAPPING (smsconfigmappingid, smsconfigid, parameter, value, mvnoid)
			VALUES (@newSmsConfigmappingId+1, @newSmsConfigId, 'password', '636fa365', 1);

			INSERT INTO TBLMSMSCONFIGMAPPING (smsconfigmappingid, smsconfigid, parameter, value, mvnoid)
			VALUES (@newSmsConfigmappingId+2, @newSmsConfigId, 'sender', 'SAVBILLN', 1);

			INSERT INTO TBLMSMSCONFIGMAPPING (smsconfigmappingid, smsconfigid, parameter, value, mvnoid)
			VALUES (@newSmsConfigmappingId+3, @newSmsConfigId, 'type', '1', 1);

			INSERT INTO TBLMSMSCONFIGMAPPING (smsconfigmappingid, smsconfigid, parameter, value, mvnoid)
			VALUES (@newSmsConfigmappingId+4, @newSmsConfigId, 'product', '1', 1);

			INSERT INTO TBLMSMSCONFIGMAPPING (smsconfigmappingid, smsconfigid, parameter, value, mvnoid)
			VALUES (@newSmsConfigmappingId+5, @newSmsConfigId, 'mobile', '{mobile}', 1);

			INSERT INTO TBLMSMSCONFIGMAPPING (smsconfigmappingid, smsconfigid, parameter, value, mvnoid)
			VALUES (@newSmsConfigmappingId+6, @newSmsConfigId, 'template', '{template}', 1);

			INSERT INTO TBLMSMSCONFIGMAPPING (smsconfigmappingid, smsconfigid, parameter, value, mvnoid)
			VALUES (@newSmsConfigmappingId+7, @newSmsConfigId, 'message', '{message}', 1);

UPDATE tblmtemplate t
SET t.smstemplatedata = "Dear {customerName}, A task with id: {caseNumber} has been marked as {caseStatus} successfully. Thank You.",
	t.emailtemplatedata = "Dear {customerName}, <br /> <br /> A task with id: {caseNumber} has been marked as {caseStatus} successfully. <br /> <br /> Thank You.<br /> Savbill NetTech." where templatename = 'Task Close Message' ;

UPDATE tblmtemplate t
SET t.smstemplatedata = "Dear {username}, A task has been created successfully with id: {caseNumber}.The task duration is from {startDate} to {endDate}. Thank You.",
	t.emailtemplatedata = "Dear {username},<br /> <br /> A task has been created successfully with id: {caseNumber}.<br /> <br />The task duration is from {startDate} to {endDate}. Thank You." where templatename = 'Task' ;

UPDATE tblmtemplate t
SET t.smstemplatedata = "Dear {username}, A task with id: {caseNumber} has been Re-Schedules successfully .The task duration is from {startDate} to {endDate}. Thank You.",
	t.emailtemplatedata = "Dear {username},<br /> <br /> A task with id: {caseNumber} has been Re-Schedules successfully .<br /> <br />The task duration is from {startDate} to {endDate}. Thank You." where templatename = 'Task Reschedule' ;

UPDATE tblmtemplate t
SET t.smstemplatedata = "Dear Vauled Staff, {teamStaff} has given remark : {remark} for task {ticketNumber} .- Savbill NetTech.",
	t.emailtemplatedata = "Dear Vauled Staff, {teamStaff} has given remark : {remark} for task {ticketNumber} .- Savbill NetTech." where templatename = 'Task Remark Message' ;
